// Filtrar solo las reservas que correspondan a la fecha de mañana en Costa Rica
const tomorrow = new Date();
tomorrow.setDate(tomorrow.getDate() + 1);
const tomorrowStr = tomorrow.toISOString().split('T')[0];

const items = $input.all();
const results = [];

for (const item of items) {
  const doc = item.json.document;
  if (!doc || !doc.fields) continue;

  const tourDate = doc.fields.date?.stringValue || doc.fields.tourDate?.stringValue;
  if (tourDate === tomorrowStr) {
    const customer = doc.fields.customer?.mapValue?.fields || {};
    let rawPhone = doc.fields.customerPhone?.stringValue || customer.phone?.stringValue || '';
    rawPhone = String(rawPhone).replace(/[^0-9]/g, '');
    if (rawPhone.length === 8) rawPhone = '506' + rawPhone;

    results.push({
      bookingId: doc.name.split('/').pop(),
      customerName: doc.fields.customerName?.stringValue || customer.name?.stringValue || 'Viajero',
      customerPhone: rawPhone,
      tourName: doc.fields.tourName?.stringValue || 'Tour en Costa Rica',
      time: doc.fields.time?.stringValue || '08:00 AM',
      meetingPoint: doc.fields.pickupHotel?.stringValue || doc.fields.meetingPoint?.stringValue || 'Lugar indicado en el voucher'
    });
  }
}

return results;

